const dictionaries = {en,'zh-CN':{...en,...cn},'zh-TW':{...en,...tw},es};
const STORAGE_KEY='exercise-locale';
let locale;
export function getLocale(){if(locale)return locale;try{const saved=localStorage.getItem(STORAGE_KEY);return dictionaries[saved]?saved:'zh-CN';}catch{return 'zh-CN';}}
export function t(key,values={}){let text=dictionaries[getLocale()][key]??en[key]??key;for(const [name,value] of Object.entries(values))text=text.replaceAll('{'+name+'}',String(value));return text;}
export function applyTranslations(root=document){document.documentElement.lang=getLocale();const attrs=[['data-i18n','textContent'],['data-i18n-placeholder','placeholder'],['data-i18n-aria-label','aria-label'],['data-i18n-title','title']];for(const [attribute,target] of attrs){for(const element of root.querySelectorAll('['+attribute+']')){const value=t(element.getAttribute(attribute));if(target==='textContent')element.textContent=value;else element.setAttribute(target,value);}}}
export function setLocale(value){locale=dictionaries[value]?value:'zh-CN';try{localStorage.setItem(STORAGE_KEY,locale);}catch{}applyTranslations();window.dispatchEvent(new CustomEvent('localechange'));}
